alter table public.organization_contacts add column if not exists linked_user_id uuid references auth.users (id) on delete set null;
create index if not exists organization_contacts_linked_user_id_idx on public.organization_contacts (linked_user_id);
create unique index if not exists organization_contacts_organization_email_ci_uidx on public.organization_contacts (organization_id, lower(trim(email)));
alter table public.organization_invites add column if not exists recipient_email text, add column if not exists recipient_name text, add column if not exists source_contact_id uuid references public.organization_contacts (id) on delete set null;
alter table public.organization_invites drop constraint if exists organization_invites_recipient_email_check;
alter table public.organization_invites add constraint organization_invites_recipient_email_check check (recipient_email is null or recipient_email ~* '^[^@[:space:]]+@[^@[:space:]]+[.][^@[:space:]]+$');
create index if not exists organization_invites_recipient_email_idx on public.organization_invites (organization_id, lower(trim(recipient_email))) where recipient_email is not null;
create index if not exists organization_invites_source_contact_id_idx on public.organization_invites (source_contact_id) where source_contact_id is not null;
update public.organization_contacts as contact set linked_user_id = membership.user_id from public.organization_memberships as membership join public.profiles as profile on profile.id = membership.user_id where membership.organization_id = contact.organization_id and lower(trim(profile.email)) = lower(trim(contact.email)) and contact.linked_user_id is distinct from membership.user_id;
create or replace function public.redeem_invite_code(input_code text) returns jsonb language plpgsql security definer set search_path = public as $$ declare current_user_id uuid := auth.uid(); current_user_email text; invite_record public.organization_invites%rowtype; next_member_count integer; target_user_limit integer; begin if current_user_id is null then raise exception 'Authentication required.'; end if; select lower(trim(coalesce(profile.email, auth.jwt() ->> 'email', ''))) into current_user_email from (select 1) as seed left join public.profiles as profile on profile.id = current_user_id; select * into invite_record from public.organization_invites where lower(code) = lower(trim(input_code)) order by created_at desc limit 1; if invite_record.id is null then raise exception 'Invite code is invalid.'; end if; if exists (select 1 from public.organization_memberships where organization_id = invite_record.organization_id and user_id = current_user_id) then update public.organization_contacts set linked_user_id = current_user_id where organization_id = invite_record.organization_id and current_user_email <> '' and lower(trim(email)) = current_user_email and linked_user_id is distinct from current_user_id; return jsonb_build_object('ok', true, 'already_member', true, 'organization_id', invite_record.organization_id); end if; if invite_record.is_disabled = true or (invite_record.expires_at is not null and invite_record.expires_at <= now()) or invite_record.redeemed_uses >= invite_record.max_uses then raise exception 'Invite code is invalid or expired.'; end if; select count(*), max(organization.user_limit) into next_member_count, target_user_limit from public.organization_memberships as membership join public.organizations as organization on organization.id = invite_record.organization_id where membership.organization_id = invite_record.organization_id; if coalesce(next_member_count, 0) >= coalesce(target_user_limit, 0) then raise exception 'This library has reached its user limit.'; end if; insert into public.organization_memberships (organization_id, user_id, role, created_by) values (invite_record.organization_id, current_user_id, invite_record.role, invite_record.created_by); update public.organization_invites set redeemed_uses = redeemed_uses + 1 where id = invite_record.id; update public.organization_contacts set linked_user_id = current_user_id where organization_id = invite_record.organization_id and current_user_email <> '' and lower(trim(email)) = current_user_email and linked_user_id is distinct from current_user_id; return jsonb_build_object('ok', true, 'organization_id', invite_record.organization_id); end; $$;;
